      case data do
        <<au::binary-size(len), rest::binary>> -> {{:ok, au}, rest}
        _else -> {{:error, "Couldn't consume remaining data"}, data}
      end
    end)

  case result do
    {{:ok, aus}, <<>>} ->
      {:ok, aus}

    {{:error, reason}, data} ->
      {:error, {reason, data}}

    {{:ok, aus}, data} ->
      {:error, {"Parsing succeeded but did not consume remaining data", aus, data}}
  end
end

